class AddNotesDialogController{constructor($mdDialog,toastrService,DispatchData,id,fieldName,title,job){this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this.id=id;this.title=title;this.job=job;this._fieldName=fieldName;this.note=""}async submit(note){try{const callData={call:"updateDetailField",field:this._fieldName,value:note,jobID:this.job.id};this.job.bulkJob?await this.DispatchData.addBulkJobNote(this.job.id,callData.value,FirstName,job.preBook):await this.DispatchData.addNote(this.job.id,callData.value,FirstName,this.job.preBook);this.toastrService.showSuccessToast("Note added to job successfully");this.$mdDialog.hide()}catch(error){this.toastrService.showErrorToast(error.message)}}cancel(){this.$mdDialog.cancel()}}